const optionIds = ["A","B","C","D"];

function choiceItem({ id, question, options, answer, evidence, explanationZh, whyNot = {} }) {
  return {
    id,
    question,
    responseType: "single_choice",
    options: options.map((option,index) => typeof option === "string" ? { id:optionIds[index], text:option } : { id:optionIds[index], ...option }),
    answer,
    explanationZh,
    distractorRationales: whyNot,
    evidence,
  };
}

function listeningSet({ id, taskType, level, topic, title, directions, prepSeconds, segments, items, stimulus = null, sharedOptions, strategyTags, vocabularyTags }) {
  const transcriptWords = segments.flatMap(segment => segment.text.trim().split(/\s+/)).filter(Boolean).length;
  return {
    id,
    domain: "general",
    skill: "listening",
    taskType,
    formatAligned: true,
    level,
    topic,
    title,
    directions,
    prepSeconds,
    maxPlays: 2,
    audio: {
      asset: `audio/${id}.mp3`,
      durationEstimateSeconds: Math.max(20,Math.round(transcriptWords / 2.25)),
      segments,
    },
    stimulus,
    ...(sharedOptions ? { sharedOptions } : {}),
    items,
    strategyTags,
    vocabularyTags,
  };
}

function pictureSet({ id, level, topic, title, context, speaker, voiceCue, script, question, options, answer, evidence, explanationZh, whyNot, vocabularyTags }) {
  return listeningSet({
    id,
    taskType: "listening_picture_mc",
    level,
    topic,
    title,
    directions: "Listen to the recording and choose the correct picture.",
    prepSeconds: 10,
    segments: [
      { speaker:"Narrator", voiceCue:"Neutral British woman; clear exam pace", text:context },
      { speaker, voiceCue, text:script },
    ],
    items: [choiceItem({ id:"q1", question, options, answer, evidence, explanationZh, whyNot })],
    strategyTags: ["picture choice","visual detail","paraphrase"],
    vocabularyTags,
  });
}

function oneQuestionSet({ id, level, topic, title, context, speaker, voiceCue, script, item, vocabularyTags }) {
  return listeningSet({
    id,
    taskType: "listening_one_question_mc",
    level,
    topic,
    title,
    directions: "Listen to the short recording and choose the correct answer.",
    prepSeconds: 10,
    segments: [
      { speaker:"Narrator", voiceCue:"Neutral British woman; clear exam pace", text:context },
      { speaker, voiceCue, text:script },
    ],
    items: [choiceItem({ id:"q1", ...item })],
    strategyTags: ["short recording","speaker purpose","paraphrase"],
    vocabularyTags,
  });
}

function twoQuestionSet({ id, level, topic, title, context, segments, items, vocabularyTags }) {
  return listeningSet({
    id,
    taskType: "listening_two_question_mc",
    level,
    topic,
    title,
    directions: "Listen to the recording and answer both questions. The information follows the question order.",
    prepSeconds: 15,
    segments: [
      { speaker:"Narrator", voiceCue:"Neutral British woman; clear exam pace", text:context },
      ...segments,
    ],
    items: items.map((item,index) => choiceItem({ id:`q${index + 1}`, ...item })),
    strategyTags: ["short conversation","ordered evidence","decision"],
    vocabularyTags,
  });
}

function fiveQuestionSet({ id, level, topic, title, context, segments, items, vocabularyTags }) {
  return listeningSet({
    id,
    taskType: "listening_five_question_mc",
    level,
    topic,
    title,
    directions: "Listen to the extended recording and answer the five questions. The information follows the question order.",
    prepSeconds: 45,
    segments: [
      { speaker:"Narrator", voiceCue:"Neutral British woman; clear exam pace", text:context },
      ...segments,
    ],
    items: items.map((item,index) => choiceItem({ id:`q${index + 1}`, ...item })),
    strategyTags: ["extended listening","ordered evidence","attitude","inference"],
    vocabularyTags,
  });
}

function completionSet({ id, level, topic, title, context, speaker, voiceCue, script, notes, items, vocabularyTags }) {
  return listeningSet({
    id,
    taskType: "listening_note_completion",
    level,
    topic,
    title,
    directions: "Listen to the speaker and complete the five gaps with no more than three words from the recording.",
    prepSeconds: 45,
    segments: [
      { speaker:"Narrator", voiceCue:"Neutral British woman; clear exam pace", text:context },
      { speaker, voiceCue, text:script },
    ],
    stimulus: { format:"notes", text:notes },
    items: items.map((item,index) => ({
      id:`q${index + 1}`,
      question:item.question,
      responseType:"short_text",
      answer:item.answers,
      maxWords:item.maxWords,
      explanationZh:item.explanationZh,
      evidence:item.evidence,
    })),
    strategyTags: ["sentence completion","ordered evidence","exact wording"],
    vocabularyTags,
  });
}

function matchingSet({ id, taskType, level, topic, title, context, segments, sharedOptions, items, directions, vocabularyTags }) {
  return listeningSet({
    id,
    taskType,
    level,
    topic,
    title,
    directions,
    prepSeconds:45,
    segments:[
      { speaker:"Narrator", voiceCue:"Neutral British woman; clear exam pace", text:context },
      ...segments,
    ],
    sharedOptions,
    items:items.map(item => ({ ...item, responseType:"matching" })),
    strategyTags:["speaker matching","gist","paraphrase"],
    vocabularyTags,
  });
}

